#!/usr/bin/env python3
import os, sys, socket, threading, time, json, uuid, random, hashlib, hmac, select, errno, signal
from typing import Optional, Tuple, Dict, Any

CONTROL_PORT = 7835
VERSION = "bore-cli 0.6.0"
DESC = "A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls."

# ---------- CLI help / errors ----------

def prog() -> str:
    return os.path.basename(sys.argv[0]) or "executable"

def root_help(name=None) -> str:
    p = name or prog()
    return f"""{DESC}

Usage: {p} <COMMAND>

Commands:
  local   Starts a local proxy to the remote server
  server  Runs the remote proxy server
  help    Print this message or the help of the given subcommand(s)

Options:
  -h, --help     Print help
  -V, --version  Print version
"""

def local_help(name=None) -> str:
    p = name or prog()
    return f"""Starts a local proxy to the remote server

Usage: {p} local [OPTIONS] --to <TO> <LOCAL_PORT>

Arguments:
  <LOCAL_PORT>  The local port to expose [env: BORE_LOCAL_PORT=]

Options:
  -l, --local-host <HOST>  The local host to expose [default: localhost]
  -t, --to <TO>            Address of the remote server to expose local ports to [env: BORE_SERVER=]
  -p, --port <PORT>        Optional port on the remote server to select [default: 0]
  -s, --secret <SECRET>    Optional secret for authentication [env: BORE_SECRET]
  -h, --help               Print help
"""

def server_help(name=None) -> str:
    p = name or prog()
    return f"""Runs the remote proxy server

Usage: {p} server [OPTIONS]

Options:
      --min-port <MIN_PORT>          Minimum accepted TCP port number [env: BORE_MIN_PORT=] [default: 1024]
      --max-port <MAX_PORT>          Maximum accepted TCP port number [env: BORE_MAX_PORT=] [default: 65535]
  -s, --secret <SECRET>              Optional secret for authentication [env: BORE_SECRET]
      --bind-addr <BIND_ADDR>        IP address to bind to, clients must reach this [default: 0.0.0.0]
      --bind-tunnels <BIND_TUNNELS>  IP address where tunnels will listen on, defaults to --bind-addr
  -h, --help                         Print help
"""

def eprint(s: str = ""):
    print(s, file=sys.stderr)

def cli_error(msg: str, usage: Optional[str] = None, tip: Optional[str] = None, code: int = 2):
    eprint(f"error: {msg}")
    eprint()
    if tip:
        eprint(f"  tip: {tip}")
        eprint()
    if usage:
        eprint(usage)
        eprint()
    eprint("For more information, try '--help'.")
    sys.exit(code)

def runtime_error(msg: str, cause: Optional[BaseException] = None):
    eprint(f"Error: {msg}")
    if cause is not None:
        eprint()
        eprint("Caused by:")
        eprint(f"    {format_cause(cause)}")
    sys.exit(1)

def format_cause(e: BaseException) -> str:
    if isinstance(e, socket.timeout) or isinstance(e, TimeoutError):
        return "timed out"
    if isinstance(e, socket.gaierror):
        return "failed to lookup address information: Name or service not known"
    if isinstance(e, ConnectionRefusedError):
        return "Connection refused (os error 111)"
    if isinstance(e, OSError):
        if e.errno is not None:
            # Match Rust std::io formatting for the common cases.
            if e.errno == errno.EADDRINUSE:
                return "Address already in use (os error 98)"
            if e.errno == errno.EACCES:
                return "Permission denied (os error 13)"
            if e.errno == errno.ECONNREFUSED:
                return "Connection refused (os error 111)"
        return str(e)
    return str(e)

def parse_u16(val: str, what: str) -> int:
    try:
        if val.startswith('-'):
            # Rust's u16 parser reports invalid digit for negatives.
            raise ValueError('invalid digit found in string')
        n = int(val, 10)
    except ValueError:
        cli_error(f"invalid value '{val}' for '{what}': invalid digit found in string")
    if n < 0 or n > 65535:
        cli_error(f"invalid value '{val}' for '{what}': {val} is not in 0..=65535")
    return n

def parse_ip(val: str, opt: str) -> str:
    try:
        socket.inet_pton(socket.AF_INET, val)
        return val
    except OSError:
        pass
    try:
        socket.inet_pton(socket.AF_INET6, val)
        return val
    except OSError:
        cli_error(f"invalid value '{val}' for '{opt}': invalid IP address syntax")

# ---------- protocol helpers ----------

class MsgSocket:
    def __init__(self, sock: socket.socket):
        self.sock = sock
        self.buf = b''
        self.wlock = threading.Lock()
    def send_msg(self, obj: Any):
        if isinstance(obj, str):
            data = json.dumps(obj, separators=(',', ':')).encode() + b'\0'
        else:
            data = json.dumps(obj, separators=(',', ':')).encode() + b'\0'
        with self.wlock:
            self.sock.sendall(data)
    def recv_msg(self, timeout: Optional[float] = None) -> Optional[Any]:
        old = self.sock.gettimeout()
        if timeout is not None:
            self.sock.settimeout(timeout)
        try:
            while b'\0' not in self.buf:
                data = self.sock.recv(4096)
                if not data:
                    return None
                self.buf += data
            raw, self.buf = self.buf.split(b'\0', 1)
            if raw == b'':
                return None
            return json.loads(raw.decode())
        finally:
            if timeout is not None:
                self.sock.settimeout(old)
    def drain_buffer_to(self, other: socket.socket):
        if self.buf:
            data = self.buf
            self.buf = b''
            other.sendall(data)


def auth_digest(challenge: str, secret: str) -> str:
    # Observed protocol: HMAC-SHA256 over the UUID's 16 raw bytes using
    # SHA256(secret) as the HMAC key.
    key = hashlib.sha256(secret.encode()).digest()
    msg = uuid.UUID(challenge).bytes
    return hmac.new(key, msg, hashlib.sha256).hexdigest()


def log(component: str, message: str):
    # The original uses tracing with timestamps and colors. Keep the stable,
    # user-visible fields while avoiding nondeterministic decoration.
    print(f"INFO {component}: {message}", flush=True)

def warn(component: str, message: str):
    print(f"WARN {component}: {message}", flush=True)

# ---------- forwarding ----------

def pipe_bidirectional(a: socket.socket, b: socket.socket, initial_a_to_b: bytes = b'', initial_b_to_a: bytes = b''):
    if initial_a_to_b:
        try: b.sendall(initial_a_to_b)
        except OSError: pass
    if initial_b_to_a:
        try: a.sendall(initial_b_to_a)
        except OSError: pass
    sockets = [a, b]
    try:
        while sockets:
            r, _, _ = select.select(sockets, [], [], 1.0)
            if not r:
                continue
            for s in r:
                try:
                    data = s.recv(65536)
                except OSError:
                    data = b''
                other = b if s is a else a
                if not data:
                    try: other.shutdown(socket.SHUT_WR)
                    except OSError: pass
                    try: s.close()
                    except OSError: pass
                    if s in sockets: sockets.remove(s)
                    continue
                try:
                    other.sendall(data)
                except OSError:
                    try: s.close()
                    except OSError: pass
                    try: other.close()
                    except OSError: pass
                    return
    finally:
        for s in (a, b):
            try: s.close()
            except OSError: pass

# ---------- server ----------

class ServerState:
    def __init__(self, min_port: int, max_port: int, secret: Optional[str], bind_addr: str, bind_tunnels: str):
        self.min_port = min_port
        self.max_port = max_port
        self.secret = secret
        self.bind_addr = bind_addr
        self.bind_tunnels = bind_tunnels
        self.sessions: Dict[int, 'Session'] = {}
        self.pending: Dict[str, Tuple[socket.socket, 'Session']] = {}
        self.lock = threading.RLock()

class Session:
    def __init__(self, state: ServerState, port: int, ms: MsgSocket, peer: Tuple[str,int]):
        self.state = state
        self.port = port
        self.ms = ms
        self.peer = peer
        self.listener: Optional[socket.socket] = None
        self.alive = True
        self.threads = []
    def close(self):
        self.alive = False
        try: self.ms.sock.close()
        except OSError: pass
        if self.listener:
            try: self.listener.close()
            except OSError: pass
        with self.state.lock:
            if self.state.sessions.get(self.port) is self:
                del self.state.sessions[self.port]
            for k,(sock,sess) in list(self.state.pending.items()):
                if sess is self:
                    try: sock.close()
                    except OSError: pass
                    del self.state.pending[k]


def server_authenticate(state: ServerState, ms: MsgSocket) -> Tuple[bool, Optional[Any]]:
    """Returns (ok, first_non_auth_message_or_None)."""
    if not state.secret:
        return True, None
    challenge = str(uuid.uuid4())
    try:
        ms.send_msg({"Challenge": challenge})
        msg = ms.recv_msg(timeout=30)
    except Exception:
        return False, None
    if not (isinstance(msg, dict) and "Authenticate" in msg):
        try: ms.send_msg({"Error": "server requires secret, but no secret was provided"})
        except OSError: pass
        return False, msg
    expected = auth_digest(challenge, state.secret)
    if str(msg.get("Authenticate")) != expected:
        try: ms.send_msg({"Error": "invalid secret"})
        except OSError: pass
        return False, None
    return True, None


def choose_and_bind_tunnel(state: ServerState, requested: int) -> Tuple[Optional[int], Optional[socket.socket], Optional[str]]:
    if requested != 0 and (requested < state.min_port or requested > state.max_port):
        return None, None, "client port number not in allowed range"
    candidates = []
    if requested:
        candidates = [requested]
    else:
        candidates = list(range(state.min_port, state.max_port + 1))
        random.shuffle(candidates)
    for port in candidates:
        with state.lock:
            if port in state.sessions:
                if requested:
                    return None, None, "port already in use"
                continue
        ls = socket.socket(socket.AF_INET6 if ':' in state.bind_tunnels else socket.AF_INET, socket.SOCK_STREAM)
        ls.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            ls.bind((state.bind_tunnels, port))
            ls.listen(128)
            return port, ls, None
        except OSError:
            try: ls.close()
            except OSError: pass
            if requested:
                return None, None, "port already in use"
            continue
    return None, None, "no ports available"


def tunnel_accept_loop(sess: Session):
    assert sess.listener is not None
    while sess.alive:
        try:
            ext, addr = sess.listener.accept()
        except OSError:
            break
        cid = str(uuid.uuid4())
        log("bore_cli::server", f"new connection addr={addr[0]}:{addr[1]} port={sess.port}")
        with sess.state.lock:
            sess.state.pending[cid] = (ext, sess)
        try:
            sess.ms.send_msg({"Connection": cid})
        except OSError:
            with sess.state.lock:
                sess.state.pending.pop(cid, None)
            try: ext.close()
            except OSError: pass
            break


def heartbeat_loop(sess: Session):
    while sess.alive:
        time.sleep(0.3)
        try:
            sess.ms.send_msg("Heartbeat")
        except OSError:
            break


def handle_control(conn: socket.socket, peer, state: ServerState):
    log("bore_cli::server", "incoming connection")
    ms = MsgSocket(conn)
    sess: Optional[Session] = None
    try:
        ok, first = server_authenticate(state, ms)
        if not ok:
            warn("bore_cli::server", "server handshake failed")
            return
        msg = first if first is not None else ms.recv_msg(timeout=60)
        if msg is None:
            return
        if isinstance(msg, dict) and "Hello" in msg:
            try:
                req = int(msg["Hello"])
            except Exception:
                try: ms.send_msg({"Error": "invalid hello"})
                except OSError: pass
                return
            port, listener, err = choose_and_bind_tunnel(state, req)
            if err:
                try: ms.send_msg({"Error": err})
                except OSError: pass
                return
            assert port is not None and listener is not None
            sess = Session(state, port, ms, peer)
            sess.listener = listener
            with state.lock:
                state.sessions[port] = sess
            ms.send_msg({"Hello": port})
            log("bore_cli::server", f"new client host={peer[0]} port={port}")
            threading.Thread(target=tunnel_accept_loop, args=(sess,), daemon=True).start()
            threading.Thread(target=heartbeat_loop, args=(sess,), daemon=True).start()
            # Keep the control channel alive until EOF.
            while sess.alive:
                m = ms.recv_msg(timeout=None)
                if m is None:
                    break
                # Heartbeats from clients are not part of the observed protocol;
                # ignore any extra messages.
            return
        if isinstance(msg, dict) and "Accept" in msg:
            cid = str(msg["Accept"])
            with state.lock:
                pending = state.pending.pop(cid, None)
            if pending is None:
                try: ms.send_msg({"Error": "connection not found"})
                except OSError: pass
                return
            ext, owner = pending
            log("bore_cli::server", f"forwarding connection id={cid}")
            # Any bytes already read beyond the NUL terminator belong to the raw stream.
            buffered = ms.buf
            ms.buf = b''
            pipe_bidirectional(conn, ext, initial_a_to_b=buffered)
            log("bore_cli::server", "connection exited")
            return
        try: ms.send_msg({"Error": "invalid request"})
        except OSError: pass
    except (ConnectionError, OSError, json.JSONDecodeError):
        pass
    finally:
        if sess is not None:
            sess.close()
        else:
            try: conn.close()
            except OSError: pass
        log("bore_cli::server", "connection exited")


def run_server(opts):
    if opts['min_port'] > opts['max_port']:
        eprint("error: port range is empty")
        eprint()
        eprint("Usage: bore-cli <COMMAND>")
        eprint()
        eprint("For more information, try '--help'.")
        sys.exit(2)
    bind_tunnels = opts['bind_tunnels'] or opts['bind_addr']
    state = ServerState(opts['min_port'], opts['max_port'], opts['secret'], opts['bind_addr'], bind_tunnels)
    family = socket.AF_INET6 if ':' in opts['bind_addr'] else socket.AF_INET
    ls = socket.socket(family, socket.SOCK_STREAM)
    ls.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        ls.bind((opts['bind_addr'], CONTROL_PORT))
        ls.listen(128)
    except OSError as e:
        runtime_error(f"could not listen on {opts['bind_addr']}:{CONTROL_PORT}", e)
    log("bore_cli::server", f"server listening addr={opts['bind_addr']}")
    while True:
        try:
            conn, peer = ls.accept()
        except KeyboardInterrupt:
            return
        except OSError:
            continue
        threading.Thread(target=handle_control, args=(conn, peer, state), daemon=True).start()

# ---------- local client ----------

def connect_control(host: str) -> socket.socket:
    try:
        return socket.create_connection((host, CONTROL_PORT), timeout=10)
    except Exception as e:
        runtime_error(f"could not connect to {host}:{CONTROL_PORT}", e)


def local_auth_and_send_hello(ms: MsgSocket, secret: Optional[str], port: int):
    if secret:
        # Authenticated clients wait for a server challenge before sending Hello.
        msg = ms.recv_msg(timeout=30)
        if isinstance(msg, dict) and "Challenge" in msg:
            ms.send_msg({"Authenticate": auth_digest(str(msg["Challenge"]), secret)})
            ms.send_msg({"Hello": port})
            return
        if isinstance(msg, dict) and "Error" in msg:
            runtime_error(f"server error: {msg['Error']}")
        # This matches the observed hang against a no-secret server reasonably:
        # keep waiting until timeout/EOF.
        runtime_error("server did not provide authentication challenge")
    else:
        ms.send_msg({"Hello": port})


def open_authenticated_accept(host: str, secret: Optional[str], cid: str) -> MsgSocket:
    sock = connect_control(host)
    ms = MsgSocket(sock)
    if secret:
        msg = ms.recv_msg(timeout=30)
        if not (isinstance(msg, dict) and "Challenge" in msg):
            raise RuntimeError("server did not provide authentication challenge")
        ms.send_msg({"Authenticate": auth_digest(str(msg["Challenge"]), secret)})
    ms.send_msg({"Accept": cid})
    return ms


def proxy_one(host: str, secret: Optional[str], cid: str, local_host: str, local_port: int):
    log("bore_cli::client", "new connection")
    local_sock = None
    control_ms = None
    try:
        local_sock = socket.create_connection((local_host, local_port), timeout=10)
        control_ms = open_authenticated_accept(host, secret, cid)
        buffered = control_ms.buf
        control_ms.buf = b''
        pipe_bidirectional(control_ms.sock, local_sock, initial_a_to_b=buffered)
    except Exception as e:
        warn("bore_cli::client", f"proxy error err={format_cause(e) if isinstance(e, BaseException) else e}")
        try:
            if local_sock: local_sock.close()
        except OSError: pass
        try:
            if control_ms: control_ms.sock.close()
        except OSError: pass
    finally:
        log("bore_cli::client", "connection exited")


def run_local(opts):
    host = opts['to']
    sock = connect_control(host)
    ms = MsgSocket(sock)
    try:
        local_auth_and_send_hello(ms, opts['secret'], opts['port'])
        remote_port = None
        while remote_port is None:
            msg = ms.recv_msg(timeout=60)
            if msg is None:
                runtime_error("server closed connection")
            if msg == "Heartbeat":
                continue
            if isinstance(msg, dict) and "Error" in msg:
                err = msg["Error"]
                if err == "server requires secret, but no secret was provided":
                    runtime_error("server requires authentication, but no client secret was provided")
                runtime_error(f"server error: {err}")
            if isinstance(msg, dict) and "Hello" in msg:
                remote_port = int(msg["Hello"])
                break
        log("bore_cli::client", f"connected to server remote_port={remote_port}")
        log("bore_cli::client", f"listening at {host}:{remote_port}")
        while True:
            msg = ms.recv_msg(timeout=None)
            if msg is None:
                runtime_error("server closed connection")
            if msg == "Heartbeat":
                continue
            if isinstance(msg, dict) and "Error" in msg:
                runtime_error(f"server error: {msg['Error']}")
            if isinstance(msg, dict) and "Connection" in msg:
                cid = str(msg["Connection"])
                threading.Thread(target=proxy_one, args=(host, opts['secret'], cid, opts['local_host'], opts['local_port']), daemon=True).start()
    except KeyboardInterrupt:
        return

# ---------- manual parsers ----------

def take_value(args, i, opt):
    if i + 1 >= len(args):
        cli_error(f"a value is required for '{opt}' but none was supplied", usage=None)
    return args[i+1], i+2

def split_long(arg: str):
    if arg.startswith('--') and '=' in arg:
        k,v=arg.split('=',1); return k,v
    return arg,None

def parse_local(args):
    # Defaults from env.
    opts = {
        'local_host': 'localhost',
        'to': os.environ.get('BORE_SERVER'),
        'port': 0,
        'secret': os.environ.get('BORE_SECRET'),
        'local_port': None,
    }
    if os.environ.get('BORE_LOCAL_PORT'):
        opts['local_port'] = parse_u16(os.environ['BORE_LOCAL_PORT'], '<LOCAL_PORT>')
    i=0
    positionals=[]
    while i < len(args):
        a=args[i]
        if a in ('-h','--help'):
            print(local_help(), end=''); sys.exit(0)
        if a == '--':
            positionals.extend(args[i+1:]); break
        key, eqval = split_long(a)
        if key in ('-l','--local-host'):
            val = eqval
            if val is None: val,i = take_value(args,i,'--local-host <HOST>')
            else: i += 1
            opts['local_host']=val; continue
        if key in ('-t','--to'):
            val = eqval
            if val is None: val,i = take_value(args,i,'--to <TO>')
            else: i += 1
            opts['to']=val; continue
        if key in ('-p','--port'):
            val = eqval
            if val is None: val,i = take_value(args,i,'--port <PORT>')
            else: i += 1
            opts['port']=parse_u16(val, '--port <PORT>'); continue
        if key in ('-s','--secret'):
            val = eqval
            if val is None: val,i = take_value(args,i,'--secret <SECRET>')
            else: i += 1
            opts['secret']=val; continue
        if a.startswith('-'):
            cli_error(f"unexpected argument '{a}' found", usage=f"Usage: {prog()} local <LOCAL_PORT|--local-host <HOST>|--to <TO>|--port <PORT>|--secret <SECRET>>", tip=f"to pass '{a}' as a value, use '-- {a}'")
        positionals.append(a); i += 1
    if len(positionals) > 1:
        bad = positionals[1]
        cli_error(f"unexpected argument '{bad}' found", usage=f"Usage: {prog()} local <LOCAL_PORT|--local-host <HOST>|--to <TO>|--port <PORT>|--secret <SECRET>>")
    if len(positionals) == 1:
        opts['local_port'] = parse_u16(positionals[0], '<LOCAL_PORT>')
    missing=[]
    if not opts['to']:
        missing.append('  --to <TO>')
    if opts['local_port'] is None:
        missing.append('  <LOCAL_PORT>')
    if missing:
        eprint("error: the following required arguments were not provided:")
        for m in missing: eprint(m)
        eprint()
        eprint(f"Usage: {prog()} local --to <TO> <LOCAL_PORT>")
        eprint()
        eprint("For more information, try '--help'.")
        sys.exit(2)
    return opts

def parse_server(args):
    opts = {
        'min_port': parse_u16(os.environ.get('BORE_MIN_PORT','1024'), '--min-port <MIN_PORT>') if os.environ.get('BORE_MIN_PORT') else 1024,
        'max_port': parse_u16(os.environ.get('BORE_MAX_PORT','65535'), '--max-port <MAX_PORT>') if os.environ.get('BORE_MAX_PORT') else 65535,
        'secret': os.environ.get('BORE_SECRET'),
        'bind_addr': '0.0.0.0',
        'bind_tunnels': None,
    }
    i=0
    while i < len(args):
        a=args[i]
        if a in ('-h','--help'):
            print(server_help(), end=''); sys.exit(0)
        key, eqval = split_long(a)
        if key == '--min-port':
            val=eqval
            if val is None: val,i=take_value(args,i,'--min-port <MIN_PORT>')
            else: i += 1
            opts['min_port']=parse_u16(val,'--min-port <MIN_PORT>'); continue
        if key == '--max-port':
            val=eqval
            if val is None: val,i=take_value(args,i,'--max-port <MAX_PORT>')
            else: i += 1
            opts['max_port']=parse_u16(val,'--max-port <MAX_PORT>'); continue
        if key in ('-s','--secret'):
            val=eqval
            if val is None: val,i=take_value(args,i,'--secret <SECRET>')
            else: i += 1
            opts['secret']=val; continue
        if key == '--bind-addr':
            val=eqval
            if val is None: val,i=take_value(args,i,'--bind-addr <BIND_ADDR>')
            else: i += 1
            opts['bind_addr']=parse_ip(val,'--bind-addr <BIND_ADDR>'); continue
        if key == '--bind-tunnels':
            val=eqval
            if val is None: val,i=take_value(args,i,'--bind-tunnels <BIND_TUNNELS>')
            else: i += 1
            opts['bind_tunnels']=parse_ip(val,'--bind-tunnels <BIND_TUNNELS>'); continue
        if a.startswith('-'):
            cli_error(f"unexpected argument '{a}' found", usage=f"Usage: {prog()} server [OPTIONS]")
        else:
            cli_error(f"unexpected argument '{a}' found", usage=f"Usage: {prog()} server [OPTIONS]")
    return opts

def main():
    # Ignore SIGPIPE like Rust programs generally do through Result handling.
    try:
        signal.signal(signal.SIGPIPE, signal.SIG_DFL)
    except Exception:
        pass
    args=sys.argv[1:]
    if not args:
        eprint(root_help(), end=''); sys.exit(2)
    if args[0] in ('-h','--help'):
        print(root_help(), end=''); return
    if args[0] in ('-V','--version'):
        print(VERSION); return
    if args[0] == 'help':
        if len(args) == 1:
            print(root_help(), end=''); return
        if args[1] == 'local': print(local_help(), end=''); return
        if args[1] == 'server': print(server_help(), end=''); return
        cli_error(f"unrecognized subcommand '{args[1]}'", usage=f"Usage: {prog()} <COMMAND>")
    cmd=args[0]
    if cmd == 'local':
        opts=parse_local(args[1:]); run_local(opts); return
    if cmd == 'server':
        opts=parse_server(args[1:]); run_server(opts); return
    if cmd.startswith('-'):
        cli_error(f"unexpected argument '{cmd}' found", usage=f"Usage: {prog()} <COMMAND>")
    else:
        cli_error(f"unrecognized subcommand '{cmd}'", usage=f"Usage: {prog()} <COMMAND>")

if __name__ == '__main__':
    main()
